public void insert()
{
    next insert();

    boolean isPickedCases;
    METSalesInvoiceDPContext context = METSalesInvoiceDPContext::current();

    if (context)
    {
        if (context.custInvoiceTrans.METPickedCases != 0)
        {
            this.metInsertPickedCaseLine(this, context.custInvoiceTrans, context.salesLine, context.custInvoiceTrans.METPickedCases, false);
            isPickedCases = true;
        }

        if (context.custInvoiceTrans.METPickedBrokenCases != 0)
        {
            this.metInsertPickedCaseLine(this, context.custInvoiceTrans, context.salesLine, context.custInvoiceTrans.METPickedBrokenCases, true);
            isPickedCases = true;
        }
        if (isPickedCases)
        {
            this.selectForUpdate(true);
            this.delete();
        }
    }
}

private void metInsertPickedCaseLine(SalesInvoiceTmp     _salesInvoiceTmpBase,
                                  CustInvoiceTrans    _custInvoiceTrans,
                                  SalesLine           _salesLine,
                                  METCase             _qty,
                                  boolean             _isBrokenCase)
{
    SalesInvoiceTmp caseLine;

    // Copy all fields from base line - carries over ItemId, description,
    // prices, charges, tax groups, and all other mapped fields.
    caseLine.data(_salesInvoiceTmpBase);

    // Clear RecId to force a new insert rather than updating existing record.
    caseLine.RecId = 0;

    if (_isBrokenCase)
    {
        // --- Broken cases line overrides (mapping sheet - bug 351188) ---

        // Qty Supplied = picked broken cases value
        caseLine.Qty            = _qty;

        // Qty Ordered = 0 for broken case lines
        caseLine.METOrderedQty  = 0;


        // UOM = EA for broken case lines
        caseLine.SalesUnitTxt   = METConstants::unitEach;

        EcoResProduct product = EcoResProduct::findByProductNumber(_salesLine.itemid);
        Recid toUom = UnitOfMeasure::unitOfMeasureIdBySymbol(_salesLine.SalesUnit);
        Recid eaUOM = UnitOfMeasure::unitOfMeasureIdBySymbol(METConstants::unitEach);

        Qty qtyInCase = UnitOfMeasureConverter::convert(caseLine.Qty , eaUOM, toUom, NoYes::No, product.RecId, NoYes::No);

        if(qtyInCase > 0)
        {
            caseLine.METCost = caseLine.METCost * qtyInCase;
            _salesInvoiceTmpBase.METLucInclGST = _salesInvoiceTmpBase.metcaseCost * qtyInCase;

            caseLine.METGSTTotal = _salesInvoiceTmpBase.METGSTTotal * qtyInCase;
        }
    }
    else
    {
        // --- Picked cases line overrides (mapping sheet - bug 351188) ---

        // Qty Supplied = picked cases value
        caseLine.Qty            = _qty;

        // Qty Ordered = sales line SalesQty
        caseLine.METOrderedQty  = _salesLine.SalesQty;

        // UOM = sales order line unit
        caseLine.SalesUnitTxt   = _custInvoiceTrans.SalesUnit;

        caseLine.METLucInclGST = _salesInvoiceTmpBase.metcaseCost * caseLine.Qty;

        caseLine.METGSTTotal = (_salesInvoiceTmpBase.METGSTTotal/caseLine.Qty) * caseLine.Qty;

    }

    ttsbegin;
    caseLine.doInsert();
    ttscommit;
}
